import { MeshPhysicalNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { color, uniform, positionLocal, mix, vec3 } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, BoxGeometry, DirectionalLight, AmbientLight, Vector2, DoubleSide } = ctx.THREE;

  const colors = config.intent?.visualSpec?.colors ?? {
    background: '#0b0b10', surface: '#14141a', ink: '#16161d',
    paper: '#e8ecf2', accent: '#ff2a38'
  };
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];

  const group = new Group();
  const timelines = [];
  const primHandles = [];
  const disposables = [];

  // ---- Backdrop stage (vertical gradient) ----
  const bgGeo = new PlaneGeometry(7, 6);
  const bgMat = new MeshBasicNodeMaterial();
  const topC = color('#12121a');
  const botC = color('#0b0b10');
  const t = positionLocal.y.mul(1.0 / 6.0).add(0.5).clamp(0, 1);
  bgMat.colorNode = mix(botC, topC, t);
  const bg = new Mesh(bgGeo, bgMat);
  bg.position.set(0, 0, -2.5);
  group.add(bg);
  disposables.push(bgGeo, bgMat);

  // ---- Lights (node-local rim/accent) ----
  const rim = new DirectionalLight(colors.accent, 0.9);
  rim.position.set(-3, 1.5, 2);
  group.add(rim);

  const fill = new AmbientLight(colors.paper, 0.35);
  group.add(fill);

  // ---- Filmstrip ----
  const strip = new Group();
  strip.rotation.y = -18 * Math.PI / 180;
  group.add(strip);

  const captions = [
    'NA-01 MERIDIAN', 'NA-02 NOCTURNE', 'NA-03 SIGNAL',
    'NA-04 VANTAGE', 'NA-05 ARCHIVE'
  ];
  const cardW = 1.6, cardH = 1.0, pitch = 1.85;
  const focusIndex = 2; // center card
  const cardMeshes = [];
  const uvOffsets = [];

  const cardGeo = new BoxGeometry(cardW, cardH, 0.04);
  const bevelGeo = new BoxGeometry(cardW + 0.05, cardH + 0.05, 0.03);

  for (let i = 0; i < 5; i++) {
    const cardRoot = new Group();
    const dist = i - focusIndex;
    cardRoot.position.x = dist * pitch;

    const isFocus = i === focusIndex;
    const opacity = isFocus ? 1.0 : Math.max(0.55, 1.0 - Math.abs(dist) * 0.18);
    const scale = isFocus ? 1.0 : 0.92;
    cardRoot.scale.setScalar(scale);
    if (isFocus) cardRoot.rotation.y = 18 * Math.PI / 180; // counter-rotate to face camera

    // bevel frame (machined ink)
    const bevelMat = new MeshPhysicalNodeMaterial();
    bevelMat.colorNode = color(colors.ink);
    bevelMat.roughness = 0.5;
    bevelMat.metalness = 0.5;
    bevelMat.clearcoat = 0.2;
    const bevel = new Mesh(bevelGeo, bevelMat);
    bevel.position.z = -0.01;
    cardRoot.add(bevel);
    disposables.push(bevelMat);

    // card face
    const uvOff = uniform(new Vector2(0, 0));
    const cardMat = new MeshPhysicalNodeMaterial();
    cardMat.colorNode = color(colors.surface);
    cardMat.roughness = 0.55;
    cardMat.metalness = 0.2;
    cardMat.clearcoat = 0.15;
    cardMat.transparent = true;
    cardMat.opacity = opacity;
    const card = new Mesh(cardGeo, cardMat);
    cardRoot.add(card);
    disposables.push(cardMat);

    uvOffsets.push({ card, off: uvOff });
    cardMeshes.push(cardRoot);

    // caption below card
    const cap = ctx.fontAtlas.createText(captions[i], {
      fontSize: 18,
      color: isFocus ? colors.paper : colors.ink,
      align: 'center',
      letterSpacingPx: 3
    });
    cap.position.set(0, -0.75, 0.05);
    cap.scale.setScalar(0.9);
    cardRoot.add(cap);

    strip.add(cardRoot);
  }
  disposables.push(cardGeo, bevelGeo);

  // ---- Focused underline bar (accent, emissive) ----
  const barGeo = new PlaneGeometry(1.6, 0.035);
  const barMat = new MeshBasicNodeMaterial();
  barMat.colorNode = color(colors.accent).mul(1.3);
  const bar = new Mesh(barGeo, barMat);
  bar.position.set(0, -0.6, 0.06);
  bar.rotation.y = 18 * Math.PI / 180;
  strip.add(bar);
  disposables.push(barGeo, barMat);

  // ---- Load distinct textures (base + variants; fall back to base) ----
  const baseUrl = config.imageUrl ?? config.intent?.visualSpec?.imageUrl ?? '/prism-mock/home/nodes/parallax-stack.png';
  ctx.textureLoader.loadTexture(baseUrl).then((tex) => {
    uvOffsets.forEach(({ card }, idx) => {
      // distinct plates via per-card UV repeat offset (no echo)
      const t2 = tex.clone();
      t2.needsUpdate = true;
      t2.offset = new Vector2((idx * 0.13) % 1, (idx * 0.07) % 1);
      card.material.map = t2;
      card.material.colorNode = null;
      card.material.needsUpdate = true;
      disposables.push(t2);
    });
  }).catch(() => {});

  // ---- Headline & body text ----
  const headline = ctx.fontAtlas.createText('The collection', {
    fontSize: 68, color: colors.paper, align: 'left'
  });
  headline.position.set(-2.6, 1.5, 0);
  group.add(headline);

  const body = ctx.fontAtlas.createText('Five calibres. One discipline.', {
    fontSize: 26, color: colors.paper, align: 'left'
  });
  body.position.set(-2.6, -1.5, 0);
  group.add(body);

  // ---- Cinematic primitives ----
  const prims = config.cinematicPrimitives ?? [{ name: 'parallax-scroll', params: { intensity: 0.5 }, trigger: 'scroll' }];
  for (const p of prims) {
    if (ctx.primitives[p.name]) {
      const h = ctx.primitives[p.name](strip, p.params ?? {});
      if (h) primHandles.push(h);
    }
  }

  // ---- Entrance: rise-in / weighted-settle ----
  strip.position.y = 0.4;
  strip.scale.setScalar(1.04);
  const tl = gsap.timeline();
  tl.to(strip.position, { y: 0, duration: 0.7, ease: 'power3.out' }, 0);
  tl.to(strip.scale, { x: 1, y: 1, z: 1, duration: 0.9, ease: 'power4.out' }, 0.1);
  timelines.push(tl);

  // idle breathing on bar (single slow transform)
  const idle = gsap.to(bar.scale, {
    x: 1.02, duration: 2.2, ease: 'sine.inOut', yoyo: true, repeat: -1
  });
  timelines.push(idle);

  // ---- Handlers ----
  group.userData.handlers = {
    scroll: (delta) => {
      const d = (typeof delta === 'number' ? delta : (delta?.deltaY ?? 0)) * 0.001;
      uvOffsets.forEach(({ off }, i) => {
        const dir = i % 2 === 0 ? 1 : -1;
        off.value.x = Math.max(-0.04, Math.min(0.04, off.value.x + d * dir));
      });
    },
    click: () => {
      ctx.emit('navigate', { to: 'hub-collection' });
    }
  };

  // ---- Cleanup ----
  group.userData.cleanup = () => {
    timelines.forEach((tl) => tl.kill());
    primHandles.forEach((h) => h?.cleanup?.());
    disposables.forEach((d) => d?.dispose?.());
    group.traverse((o) => {
      if (o.geometry) o.geometry.dispose?.();
      if (o.material) {
        if (o.material.map) o.material.map.dispose?.();
        o.material.dispose?.();
      }
    });
  };

  return group;
}
